def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def pick_nearest(start, items):
        best = None
        best_d = None
        for item in items:
            p = pos(item, None)
            if p is None:
                continue
            d = manhattan(start, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def pick_farthest(start, items):
        best = None
        best_d = None
        for item in items:
            p = pos(item, None)
            if p is None:
                continue
            d = manhattan(start, p)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    width = observation.get("grid_width", 0) or 0
    height = observation.get("grid_height", 0) or 0
    center = (width // 2, height // 2) if width and height else self_pos

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0)]
        if height:
            corners.append((0, height - 1))
        if width:
            corners.append((width - 1, 0))
        if width and height:
            corners.append((width - 1, height - 1))
        target = pick_farthest(opp_pos, corners) or center
        move = step_toward(self_pos, target)
        if move == [0, 0]:
            move = step_away(self_pos, opp_pos)
        return move

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        target = pick_nearest(self_pos, targets)
        if target is not None:
            return step_toward(self_pos, target)
        if width and height:
            return step_toward(self_pos, center)
        return step_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_cells") or []
    target = pick_nearest(self_pos, resources)
    if target is not None:
        return step_toward(self_pos, target)

    # Fallbacks when no explicit resource targets exist.
    if width and height:
        return step_toward(self_pos, center)
    return step_away(self_pos, opp_pos)

